import json,html
OR='#F58220'; WH='#FFFFFF'; BK='#000000'; RD='#D7191C'; YL='#FFD200'
PH='<!-- PLACEHOLDER_ASSET: generated by the TCP project from MUTCD 11th Ed. Ch.6 descriptions; not from the client library; verify against FHWA Standard Highway Signs before approval -->'
def svg(w,h,body,title):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" width="{w}" height="{h}">{PH}<title>{html.escape(title)}</title>{body}</svg>'
def txt(lines,cx,cy,size,fill=BK,lh=1.1):
    n=len(lines); y0=cy-(n-1)*size*lh/2
    return ''.join(f'<text x="{cx}" y="{y0+i*size*lh}" font-family="Arial, Helvetica, sans-serif" font-weight="bold" font-size="{size}" fill="{fill}" text-anchor="middle" dominant-baseline="middle">{html.escape(l)}</text>' for i,l in enumerate(lines))
def diamond(lines,glyph='',fs=None):
    b=f'<polygon points="100,4 196,100 100,196 4,100" fill="{OR}" stroke="{BK}" stroke-width="5"/><polygon points="100,14 186,100 100,186 14,100" fill="none" stroke="{BK}" stroke-width="3"/>'
    if glyph: return svg(200,200,b+glyph,' '.join(lines))
    fs=fs or (26 if max(len(l) for l in lines)<=6 else 20 if max(len(l) for l in lines)<=9 else 16)
    return svg(200,200,b+txt(lines,100,100,fs),' '.join(lines))
def rect(w,h,lines,fill=WH,fg=BK,fs=None,arrow=None,border=True):
    b=f'<rect x="3" y="3" width="{w-6}" height="{h-6}" rx="8" fill="{fill}" stroke="{fg}" stroke-width="4"/>'
    if border: b+=f'<rect x="9" y="9" width="{w-18}" height="{h-18}" rx="5" fill="none" stroke="{fg}" stroke-width="2"/>'
    fs=fs or min(28, int((w-30)/max(len(l) for l in lines)/0.62), int((h-(40 if arrow else 20))/len(lines)/1.15))
    cy=h/2-(14 if arrow else 0)
    b+=txt(lines,w/2,cy,fs,fg)
    if arrow:
        y=h-26; x1,x2=w*0.25,w*0.75
        if arrow=='L': b+=f'<path d="M{x2} {y} H{x1+18}" stroke="{fg}" stroke-width="8"/><polygon points="{x1},{y} {x1+22},{y-14} {x1+22},{y+14}" fill="{fg}"/>'
        else: b+=f'<path d="M{x1} {y} H{x2-18}" stroke="{fg}" stroke-width="8"/><polygon points="{x2},{y} {x2-22},{y-14} {x2-22},{y+14}" fill="{fg}"/>'
    return svg(w,h,b,' '.join(lines))
