cat=[]
def add(code,name,kind,svgtext,size,section,tas,observed,status='MUTCD',notes=''):
    fn=code.replace('/','_')+'.svg'
    open('svg/'+fn,'w').write(svgtext)
    cat.append({'id':code,'mutcd_code':code if status=='MUTCD' else None,'name':name,'category':kind,
      'size_in':size,'source':section,'used_by_tas':tas,'observed_in_drafts':observed,
      'asset':{'file':'svg/'+fn,'status':'PLACEHOLDER_ASSET'},'code_status':status,'notes':notes,'version':'0.1'})
